using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=key",
            "CatalogDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: The Cosmos provider now uses "$type" as the
        // discriminator property instead of "Discriminator". For existing documents
        // that already store "Discriminator", explicitly configure the old name.
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public decimal Price { get; set; }
}

using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous I/O is no longer supported by the
    // Cosmos provider. All queries must use async methods (ToListAsync, etc.).
    async Task<List<Product>> GetExpensiveProductsAsync(CosmosDbContext db)
    {
        return await db.Products
            .Where(p => p.Price > 100)
            .ToListAsync();
    }

    // If you previously had synchronous code like:
    //   db.Products.ToList()
    // it will now throw InvalidOperationException at runtime.
    // You MUST convert to async: await db.Products.ToListAsync()
}

